pub fn is_valid_output_format(fmt: &str) -> bool { matches!(fmt, "docx" | "odt" | "rtf" | "epub" | "pdf" | "html" | "markdown" | "rst" | "latex" | "org" | "textile" | "asciidoc" | "mediawiki" | "pptx" | "beamer" | "revealjs" | "json" | "docbook" | "jats" | "man" | "plain" | "gfm" | "commonmark") }
